def _check_words():
    """Statements the S10 caption makes in words (not rendered numbers) must still hold."""
    z = fs.stat('round4/beyond/case_summary/zaraz')
    assert z['sites_ad_default'] == z['sites_ad_after_decline'] == z['sites_ad_gpc'] == 0, 'S10: Zaraz ad requests'
    assert z['selected'] == z['captured'] == 1, 'S10: Zaraz singular'
    pt = fs.stat('round4/beyond/case_summary/partytown')
    assert pt['sites_ad_subframe_default'] == 1 and pt['sites_ad_main_thread_default'] > 1, 'S10: Partytown singular/plural'


def main():
    _check_words()
    fs.reset_registry()
    out = ['% caption_supp.tex -- GENERATED by figures/v7/supp/scripts/make_captions.py; do not edit by hand.',
           '% Captions of Supplementary Figures S1-S10 (v2). Every number is rendered from analysis/outputs/stats.json or a',
           '% derived_numbers.json by the script (log: panels/captions_numbers.csv). Figure files: figS1.pdf ... figS10.pdf.', '']
    for key, text in CAPTIONS:
        body = TOK.sub(render, text)
        assert '<<' not in body, key
        out += [f'% ---- Figure {key.upper()} ({"fig" + key.upper()}.pdf)',
                f'\\caption{{{body}}}', f'\\label{{fig:{key}}}', '']
    open(os.path.join(SUPP, 'caption_supp.tex'), 'w').write('\n'.join(out))
    fs.write_registry(os.path.join(SUPP, 'panels', 'captions_numbers.csv'))
    print('wrote caption_supp.tex')


if __name__ == '__main__':
    main()
